/* eslint-env node */
/* eslint-disable @typescript-eslint/no-var-requires -- Playwright CLI scripts use CommonJS. */
const { chromium } = require('playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
async function main() {
  const { createServer } = await import('vite');
  const server = await createServer({server:{host:'127.0.0.1',port:4302,strictPort:true}});
  await server.listen();
  const browser = await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH || undefined,args:['--no-sandbox']});
  try {
    for (const theme of ['light','dark']) for (const width of [390,768,1024,1440]) {
      const context = await browser.newContext({viewport:{width,height:960},hasTouch:width<1024,reducedMotion:'reduce',acceptDownloads:true});
      await context.addInitScript(theme => { localStorage.setItem('hisabiq-theme',theme); window.print = () => undefined; }, theme);
      const page = await context.newPage(); const errors=[]; page.on('pageerror',e=>errors.push(e.message));
      const root='http://127.0.0.1:4302/#/app/';
      const choose=async(label,value)=>{await page.getByRole('combobox',{name:label,exact:true}).click();await page.getByRole('option',{name:value,exact:true}).click();};
      await page.goto(root+'expenses');
      await choose('Expense category filter','Salary');
      assert.equal(await page.locator('tbody tr').count(),1);
      await choose('Expense payment filter','Bank');
      assert.match(await page.locator('tbody').innerText(),/EXP-000060/,'split payment Bank filter');
      await choose('Expense payment filter','bKash');
      assert.match(await page.locator('tbody').innerText(),/No expenses match/);
      await page.getByRole('button',{name:'Reset',exact:true}).click();
      await choose('Expense payee filter','DESCO (Electricity)');
      assert.equal(await page.locator('tbody tr').count(),1);
      const downloadEvent=page.waitForEvent('download');await page.getByRole('button',{name:'Export',exact:true}).click();
      const download=await downloadEvent;const csv=await fs.readFile(await download.path(),'utf8');
      assert.match(csv,/EXP-000058/);assert.doesNotMatch(csv,/EXP-000060/);
      await page.getByRole('button',{name:'Reset',exact:true}).click();
      await page.getByRole('button',{name:'Add expense',exact:true}).click();
      const form=page.getByRole('dialog',{name:'Add expense',exact:true});
      await form.getByRole('textbox',{name:'Expense amount',exact:true}).fill('500');
      await form.getByRole('textbox',{name:'Description / remarks',exact:true}).fill('Counter delivery test');
      await form.getByRole('combobox',{name:'Payee',exact:true}).click();await page.getByText('Add new payee',{exact:true}).click();
      let quick=page.locator('[data-slot="dialog-content"]').last();
      await quick.getByRole('textbox',{name:/Payee name/}).fill('Counter delivery');
      await quick.getByRole('textbox',{name:/Phone/}).fill('01712345678');
      await quick.getByRole('button',{name:'Add payee',exact:true}).click();
      assert.equal(await form.getByRole('textbox',{name:'Expense amount',exact:true}).inputValue(),'500');
      assert.match(await form.getByRole('combobox',{name:'Payee',exact:true}).innerText(),/Counter delivery/);
      await form.getByRole('combobox',{name:'Expense category',exact:true}).click();await page.getByText('Add new expense category',{exact:true}).click();
      quick=page.locator('[data-slot="dialog-content"]').last();
      await quick.getByRole('textbox',{name:/Expense category name/}).fill('Delivery expense');
      await quick.getByRole('button',{name:'Add expense category',exact:true}).click();
      assert.equal(await form.getByRole('textbox',{name:'Description / remarks',exact:true}).inputValue(),'Counter delivery test');
      await form.getByRole('textbox',{name:'Expense amount',exact:true}).fill('-20');
      await form.getByRole('button',{name:'Review expense',exact:true}).click();
      assert.match(await form.getByRole('alert').innerText(),/nonnegative/);
      await form.getByRole('textbox',{name:'Expense amount',exact:true}).fill('500');
      await form.getByRole('textbox',{name:'Payment amount 1',exact:true}).fill('100');
      await form.getByRole('button',{name:'Review expense',exact:true}).click();
      assert.match(await form.getByRole('region',{name:'Expense correction impact'}).innerText(),/পাঁচশত টাকা মাত্র/);
      await form.getByRole('button',{name:'Confirm expense preview',exact:true}).click();
      await form.waitFor({state:'hidden'});
      await page.getByRole('button',{name:'Actions for EXP-000062',exact:true}).click();
      await page.getByRole('button',{name:'Correct',exact:true}).click();
      const edit=page.getByRole('dialog',{name:'Correct expense',exact:true});
      assert.equal(await edit.getByRole('textbox',{name:'Payment amount 1',exact:true}).inputValue(),'100');
      await edit.getByRole('textbox',{name:'Expense amount',exact:true}).fill('600');
      await edit.getByRole('button',{name:'Review changes',exact:true}).click();
      assert.match(await edit.getByRole('alert').innerText(),/reason/);
      await edit.getByRole('textbox',{name:'Expense correction reason',exact:true}).fill('Correct delivery charge');
      await edit.getByRole('button',{name:'Review changes',exact:true}).click();
      const correctionReview=await edit.getByRole('region',{name:'Expense correction impact'}).innerText();assert.match(correctionReview,/Previous amount ৳500/);assert.match(correctionReview,/৳600/);
      await edit.getByRole('button',{name:'Confirm preview correction',exact:true}).click();
      const detail=page.getByRole('dialog',{name:'Bill details',exact:true});
      await detail.waitFor();
      assert.match(await detail.getByRole('region',{name:'Expense preview history'}).innerText(),/Correct delivery charge/);
      await detail.locator('input[type=file]').setInputFiles({name:'receipt.png',mimeType:'image/png',buffer:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/pL8AAAAASUVORK5CYII=','base64')});
      assert.match(await detail.locator('img').first().getAttribute('src'),/^blob:/);
      const popupEvent=page.waitForEvent('popup');await detail.getByRole('button',{name:'Print',exact:true}).click();
      const popup=await popupEvent;await popup.waitForLoadState();
      assert.match(await popup.locator('body').innerText(),/EXP-000062/);assert.doesNotMatch(await popup.locator('body').innerText(),/EXP-000061/);await popup.close();
      if(process.env.EXPENSE_SCREENSHOTS && [390,1440].includes(width)) await page.screenshot({path:process.env.EXPENSE_SCREENSHOTS+`/expense-${width}-${theme}.png`});
      await detail.getByRole('button',{name:'Close',exact:true}).first().click();
      await page.getByRole('button',{name:'Actions for EXP-000062',exact:true}).click();await page.getByRole('button',{name:'Cancel expense',exact:true}).click();
      const cancel=page.getByRole('dialog',{name:'Cancel expense preview'});await cancel.getByRole('button',{name:'Confirm cancellation',exact:true}).click();
      assert.match(await cancel.getByRole('alert').innerText(),/reason/);
      await cancel.getByRole('textbox',{name:'Expense cancellation reason'}).fill('Duplicate delivery');await cancel.getByRole('button',{name:'Confirm cancellation',exact:true}).click();
      assert.equal(await page.getByRole('button',{name:'Actions for EXP-000062',exact:true}).count(),0);
      await choose('Expense status filter','Cancelled');assert.match(await page.locator('tbody').innerText(),/EXP-000062/);
      await page.locator('tbody tr').first().click();await detail.waitFor();assert.match(await detail.innerText(),/Duplicate delivery/);assert.equal(await detail.getByRole('button',{name:'Correct expense',exact:true}).count(),0);await detail.getByRole('button',{name:'Close',exact:true}).first().click();
      await page.getByRole('tab',{name:'Categories',exact:true}).click();
      const categoryRow=page.locator('tbody tr').filter({hasText:'Delivery expense'});
      await categoryRow.getByRole('button',{name:'Edit',exact:true}).click();const category=page.getByRole('dialog',{name:'Expense category editor'});
      await category.getByRole('textbox',{name:'Category name'}).fill('Delivery charges');await category.getByRole('button',{name:'Save category'}).click();
      const renamed=page.locator('tbody tr').filter({hasText:'Delivery charges'});await renamed.getByRole('button',{name:'Deactivate',exact:true}).click();assert.match(await renamed.innerText(),/Inactive/);await renamed.getByRole('button',{name:'Activate',exact:true}).click();
      await page.getByRole('tab',{name:'Payees',exact:true}).click();const payee=page.locator('tbody tr').filter({hasText:'Counter delivery'});assert.ok(await payee.getByRole('button',{name:'Deactivate'}).isDisabled());
      await payee.getByRole('button',{name:'Edit',exact:true}).click();const party=page.getByRole('dialog',{name:'Edit party'});await party.getByRole('textbox',{name:'Area',exact:true}).fill('Dhaka counter');await party.getByRole('button',{name:'Save party'}).click();await party.waitFor({state:'hidden'});
      await page.getByRole('tab',{name:'Reports',exact:true}).click();const reportPopup=page.waitForEvent('popup');await page.getByRole('button',{name:'Print',exact:true}).click();const report=await reportPopup;await report.waitForLoadState();assert.doesNotMatch(await report.locator('body').innerText(),/EXP-000062/);assert.match(await report.locator('body').innerText(),/EXP-000058/);await report.close();
      await page.goto(root+'purchases');await page.getByText('PUR-000118',{exact:true}).click();await detail.waitFor();assert.ok(await detail.getByRole('button',{name:/^Pay /}).isDisabled());assert.match(await detail.innerText(),/requires integration/);
      assert.deepEqual(errors,[]);
      assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'No page overflow');
      await context.close();console.log(`Expense actions, filters, nested quick-add, correction, cancellation, receipt, CSV/print and bill payment safety passed: ${width}px ${theme}`);
    }
  }finally{await browser.close();await server.close();}
}
main().catch(e=>{console.error(e);process.exitCode=1;});
